for lang,d in lines.items():
    os.makedirs(f'{OUT}/{lang}',exist_ok=True)
    for k,text in d.items():
        if os.path.exists(f'{OUT}/{lang}/{k}.mp3'):continue
        v,ls,pitch=cast[lang][spk[k]];tmp=f'{SP}/tmp.wav'
        subprocess.run(['python3','-m','piper','-m',f'{V}/voice-{v}/{v}.onnx','--length-scale',str(ls),'-f',tmp],input=text.encode(),check=True,capture_output=True)
        sr=int(subprocess.check_output(['ffprobe','-v','error','-show_entries','stream=sample_rate','-of','csv=p=0',tmp]).decode().strip())
        af=('silenceremove=stop_periods=-1:stop_duration=0.3:stop_threshold=-40dB:stop_silence=0.25,' if 'mls' in v else '')+f'asetrate={int(sr*pitch)},aresample=22050,atempo={1/pitch:.4f},highpass=f=80,loudnorm=I=-18:TP=-2'
        subprocess.run(['ffmpeg','-y','-loglevel','error','-i',tmp,'-af',af,'-ac','1','-ar','22050','-b:a','40k',f'{OUT}/{lang}/{k}.mp3'],check=True)
    print(lang,'ok')
